Definition afake_rng (L : alayout) (RNG : footprint) : Prop :=
  rng RNG (al_fake L) FAKESZ /\ rng RNG (shad (al_fake L)) (shlen FAKESZ) /\ rng RNG (al_dtls L) 4096.

